CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TYPE forgeos_role AS ENUM ('owner','admin','member','auditor','service_account');
CREATE TYPE forgeos_run_status AS ENUM ('queued','running','passed','failed');
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, deployment_mode text NOT NULL CHECK (deployment_mode IN ('cloud','self-hosted')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE principals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), email text, role forgeos_role NOT NULL, kind text NOT NULL CHECK (kind IN ('user','service_account')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, enabled_modules text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE secrets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, provider text, ciphertext bytea NOT NULL, iv bytea NOT NULL, auth_tag bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,name));
CREATE TABLE artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), object_key text NOT NULL, media_type text NOT NULL, size_bytes bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), provider text NOT NULL, status text NOT NULL, secret_id uuid REFERENCES secrets(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), module_id text NOT NULL, status forgeos_run_status NOT NULL DEFAULT 'queued', input jsonb NOT NULL DEFAULT '{}', result jsonb, started_at timestamptz, finished_at timestamptz);
CREATE TABLE alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), severity text NOT NULL, title text NOT NULL, acknowledged_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), title text NOT NULL, status text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE audit_events (id bigserial PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), actor_id uuid, action text NOT NULL, target text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', previous_hash text NOT NULL, hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), channel text NOT NULL, title text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX runs_project_idx ON runs(project_id, finished_at DESC); CREATE INDEX audit_workspace_idx ON audit_events(workspace_id, created_at DESC);
